mapper.select:
SELECT COUNT(*)
FROM PROJ_MEMBERS
WHERE PROJ_ID = #{projId}
  AND USER_ID = #{userId}

mapper.update:
UPDATE PROJECT_TASKS
   SET ASSIGNEE_ID = #{leaderId, jdbcType=NUMERIC},
       UPDATED_AT = SYSDATE
 WHERE PROJ_ID = #{projId, jdbcType=NUMERIC}
   AND ASSIGNEE_ID = #{userId, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM PROJ_MEMBERS
 WHERE PROJ_ID = #{projId, jdbcType=NUMERIC}
   AND USER_ID = #{userId, jdbcType=NUMERIC}

mapper.update:
UPDATE PROJ_MEMBERS
   SET PROJ_POSITION = #{projPosition, jdbcType=VARCHAR}
 WHERE PROJ_ID = #{projId, jdbcType=NUMERIC}
   AND USER_ID = #{userId, jdbcType=NUMERIC}

UPDATE PROJ_MEMBERS
   SET PROJ_ROLE = #{projRole, jdbcType=VARCHAR}
 WHERE PROJ_ID = #{projId, jdbcType=NUMERIC}
   AND USER_ID = #{userId, jdbcType=NUMERIC}

UPDATE PROJECTS
   SET LEADER_ID = #{userId, jdbcType=NUMERIC}
 WHERE PROJ_ID = #{projId, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM EVENTS
WHERE EVENT_ID = #{scheduleId, jdbcType=NUMERIC}
  AND (
        ITEM_TYPE = 'SCHEDULE'
        OR (
            ITEM_TYPE = 'PROJ'
            AND NVL(EVENT_TYPE, 'APPOINTMENT') != 'PROJECT_PERIOD'
        )
      )

DELETE FROM CONTENT_SHARES
 WHERE TARGET_TYPE = 'PROJ'
   AND TARGET_ID = #{projId, jdbcType=NUMERIC}

DELETE FROM CONTENT_REACTIONS cr
 WHERE (cr.CONTENT_TYPE = 'NOTE' AND cr.CONTENT_ID IN (
            SELECT n.NOTE_ID
              FROM NOTES n
             WHERE n.PROJ_ID = #{projId, jdbcType=NUMERIC}
        ))
    OR (cr.CONTENT_TYPE IN ('PHOTO', 'PHOTO_POST') AND cr.CONTENT_ID IN (
            SELECT pp.POST_ID
              FROM PHOTO_POSTS pp
             WHERE pp.SCOPE_TYPE = 'PROJECT'
               AND pp.SCOPE_ID = #{projId, jdbcType=NUMERIC}
        ))
    OR (cr.CONTENT_TYPE = 'BOARD' AND cr.CONTENT_ID IN (
            SELECT bp.POST_ID
              FROM BOARD_POSTS bp
             WHERE bp.PROJ_ID = #{projId, jdbcType=NUMERIC}
        ))
    OR (cr.CONTENT_TYPE = 'EVENT' AND cr.CONTENT_ID IN (
            SELECT e.EVENT_ID
              FROM EVENTS e
             WHERE e.PROJ_ID = #{projId, jdbcType=NUMERIC}
        ))
    OR (cr.CONTENT_TYPE = 'POLL' AND cr.CONTENT_ID IN (
            SELECT p.POLL_ID
              FROM POLLS p
             WHERE p.PROJ_ID = #{projId, jdbcType=NUMERIC}
        ))

DELETE FROM PHOTO_POSTS
 WHERE SCOPE_TYPE = 'PROJECT'
   AND SCOPE_ID = #{projId, jdbcType=NUMERIC}

DELETE FROM PHOTO_ALBUMS
 WHERE SCOPE_TYPE = 'PROJECT'
   AND SCOPE_ID = #{projId, jdbcType=NUMERIC}

mapper.select:
SELECT 
FROM PROJECT_PERIOD_PLANS p
WHERE p.PERIOD_PLAN_ID = #{periodPlanId, jdbcType=NUMERIC}

SELECT 
FROM PROJECT_TIME_PLANS t
WHERE t.TIME_PLAN_ID = #{timePlanId, jdbcType=NUMERIC}

mapper.update:
UPDATE PROJECT_TIME_PLANS SET SORT_ORDER=SORT_ORDER+1, UPDATED_AT=SYSDATE
WHERE PROJ_ID=#{projId, jdbcType=NUMERIC}
  AND TRUNC(START_DATE)=TO_DATE(#{startDate, jdbcType=VARCHAR}, 'YYYY-MM-DD')
  AND SORT_ORDER >= #{fromSortOrder, jdbcType=NUMERIC}

UPDATE PROJECT_TIME_PLANS SET SORT_ORDER=SORT_ORDER-1, UPDATED_AT=SYSDATE
WHERE PROJ_ID=#{projId, jdbcType=NUMERIC}
  AND TRUNC(START_DATE)=TO_DATE(#{startDate, jdbcType=VARCHAR}, 'YYYY-MM-DD')
  AND SORT_ORDER > #{deletedSortOrder, jdbcType=NUMERIC}

mapper.select:
SELECT 
FROM PROJECT_WEEKLY_PLANS w
WHERE w.PROJ_ID = #{projId, jdbcType=NUMERIC}

    AND w.DAY_OF_WEEK = #{dayOfWeek, jdbcType=NUMERIC}


    AND w.ACTIVE_YN = #{activeYn, jdbcType=CHAR}


    AND w.TASK_ID = #{taskId, jdbcType=NUMERIC}

ORDER BY w.DAY_OF_WEEK, w.START_TIME, w.SORT_ORDER, w.WEEKLY_PLAN_ID

SELECT 
FROM PROJECT_WEEKLY_PLANS w
WHERE w.WEEKLY_PLAN_ID = #{weeklyPlanId, jdbcType=NUMERIC}

SELECT NVL(MAX(SORT_ORDER), 0) + 1
FROM PROJECT_WEEKLY_PLANS
WHERE PROJ_ID = #{projId, jdbcType=NUMERIC}
  AND DAY_OF_WEEK = #{dayOfWeek, jdbcType=NUMERIC}

mapper.update:
UPDATE PROJECT_WEEKLY_PLANS
SET SORT_ORDER = #{sortOrder, jdbcType=NUMERIC},
    UPDATED_AT = SYSDATE
WHERE WEEKLY_PLAN_ID = #{weeklyPlanId, jdbcType=NUMERIC}
  AND PROJ_ID = #{projId, jdbcType=NUMERIC}

UPDATE PROJECT_WEEKLY_PLANS
SET SORT_ORDER = SORT_ORDER + 1,
    UPDATED_AT = SYSDATE
WHERE PROJ_ID = #{projId, jdbcType=NUMERIC}
  AND DAY_OF_WEEK = #{dayOfWeek, jdbcType=NUMERIC}
  AND SORT_ORDER >= #{fromSortOrder, jdbcType=NUMERIC}

UPDATE PROJECT_WEEKLY_PLANS
SET SORT_ORDER = SORT_ORDER - 1,
    UPDATED_AT = SYSDATE
WHERE PROJ_ID = #{projId, jdbcType=NUMERIC}
  AND DAY_OF_WEEK = #{dayOfWeek, jdbcType=NUMERIC}
  AND SORT_ORDER > #{deletedSortOrder, jdbcType=NUMERIC}

mapper.delete:
DELETE FROM PROJECT_WEEKLY_PLANS
WHERE WEEKLY_PLAN_ID = #{weeklyPlanId, jdbcType=NUMERIC}
  AND PROJ_ID = #{projId, jdbcType=NUMERIC}

mapper.select:
SELECT COUNT(*)
  FROM CONTENT_SHARES s
 WHERE s.CONTENT_TYPE = #{planType, jdbcType=VARCHAR}
   AND s.CONTENT_ID = #{planId, jdbcType=NUMERIC}
   AND s.TARGET_TYPE = 'USER'
   AND s.TARGET_ID = #{userId, jdbcType=NUMERIC}
   AND UPPER(NVL(s.PERMISSION_TYPE, 'VIEW')) = 'EDIT'
   AND s.ACTIVE_YN = 'Y'
   AND NVL(s.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED'
   AND (s.EXPIRES_AT IS NULL OR s.EXPIRES_AT >= SYSDATE)

mapper.delete:
DELETE FROM CONTENT_SHARES
 WHERE CONTENT_TYPE = #{planType, jdbcType=VARCHAR}
   AND CONTENT_ID = #{planId, jdbcType=NUMERIC}
   AND TARGET_TYPE = 'USER'
   AND UPPER(NVL(PERMISSION_TYPE, 'VIEW')) = 'EDIT'

